// SchedulerServiceServer is the server API for SchedulerService service.
// All implementations should embed UnimplementedSchedulerServiceServer
// for forward compatibility.
//
// This API represents a scheduler service: a durable, Postgres-backed job
// queue that delivers each job's payload to a gRPC method.
//
// # Resource model
//
//   - [Queue][malonaz.scheduler.v1.Queue] resources are the methods jobs are
//     delivered to, each with its endpoint and execution policy. The dispatcher
//     creates them from the methods it discovers over its endpoints' gRPC
//     reflection; clients read, pause and resume them.
//     Format: queues/{queue}
//   - [Job][malonaz.scheduler.v1.Job] resources are system-wide at the root, or
//     hang off the organization or user they run on behalf of.
//     Format: jobs/{job}
//     Format: organizations/{organization}/jobs/{job}
//     Format: organizations/{organization}/users/{user}/jobs/{job}
//   - [Schedule][malonaz.scheduler.v1.Schedule] resources declare recurring
//     work: a cron expression and a payload template from which one job is
//     created per tick, under the schedule's parent.
//     Format: schedules/{schedule}
//     Format: organizations/{organization}/schedules/{schedule}
//     Format: organizations/{organization}/users/{user}/schedules/{schedule}
//
// # Scheduling
//
// A job is due at its `schedule_time` (at creation when unset). Due jobs of
// RUNNING queues are claimed highest `priority` first, then in due order,
// across every parent, within each queue's `max_concurrency`. A job with an
// `expire_time` must have started by then: it fails with DEADLINE_EXCEEDED if
// still PENDING at expiry, and a retry whose backoff would reach past it fails
// at once. A `unique_key` coalesces work: at most one PENDING and one RUNNING
// job exist per key, so a burst of keyed creates yields one run plus, if one
// was in flight, a single trailing run.
//
// # Delivery
//
// At creation, a job's payload type URL selects its queue. The dispatcher
// claims due PENDING jobs, invokes the queue's method on its endpoint with the
// payload as request body under the queue's attempt timeout, and records the
// outcome: SUCCEEDED with the response, or PENDING again with the next attempt
// scheduled after the backoff, or FAILED with the error once attempts are
// exhausted or the error is not retryable. A method may attach a
// `google.rpc.RetryInfo` detail to its error to set the wait before the next
// attempt. Every attempt is recorded in the job's `metadata`.
//
// Every call carries the job's resource name in the `x-scheduler-job` request
// metadata, which methods pass to ReportJobProgress.
//
// # Recurrence
//
// An ENABLED schedule is due at its `next_schedule_time`. At each tick the
// scheduler creates the job the schedule describes — `schedule_time` the
// tick, `expire_time` the tick plus the schedule's `run_window` (the next
// tick when unset), labelled `scheduler.malonaz.com/schedule` — and advances
// `next_schedule_time` to the first cron occurrence after now. A tick reached
// after its run window closed is skipped and counted in `missed_tick_count`:
// downtime is never caught up. A tick's job is created idempotently, so a
// pass interrupted after the insert replays into the same job.
//
// # Long-running operations
//
// A job of a method whose response type is `google.longrunning.Operation`
// (AIP-151) is an operation, named `{parent}/operations/{job}`. The method must return
// it done: its `response` or `error` is recorded as the job's outcome, and an
// unfinished operation fails the job with FAILED_PRECONDITION without retry.
// `WaitJob` backs `WaitOperation`.
//
// A running job holds a lease that the dispatcher renews while the call is in
// flight; jobs whose lease lapses (crashed dispatcher) are returned to PENDING.
//
// Terminal jobs are kept for the scheduler's retention and deleted at their
// `purge_time`.
type SchedulerServiceServer interface {
	// Create a queue. No two queues may share a request type. The queue starts
	// RUNNING. Meant for the dispatcher, which creates one per method it
	// discovers; see [Queue][malonaz.scheduler.v1.Queue].
	//
	// See: https://google.aip.dev/133 (Standard methods: Create).
	CreateQueue(context.Context, *CreateQueueRequest) (*v1.Queue, error)
	// Get a queue.
	//
	// See: https://google.aip.dev/131 (Standard methods: Get).
	GetQueue(context.Context, *GetQueueRequest) (*v1.Queue, error)
	// Update a queue. The new policy and endpoint apply to attempts claimed
	// after the update.
	//
	// See: https://google.aip.dev/134 (Standard methods: Update).
	UpdateQueue(context.Context, *UpdateQueueRequest) (*v1.Queue, error)
	// Delete a queue. Fails with FAILED_PRECONDITION while a PENDING or RUNNING
	// job references it.
	//
	// See: https://google.aip.dev/135 (Standard methods: Delete).
	DeleteQueue(context.Context, *DeleteQueueRequest) (*emptypb.Empty, error)
	// List queues.
	//
	// See: https://google.aip.dev/132 (Standard methods: List).
	ListQueues(context.Context, *ListQueuesRequest) (*ListQueuesResponse, error)
	// Get multiple queues in a single request.
	//
	// See: https://google.aip.dev/231 (Batch methods: Get).
	BatchGetQueues(context.Context, *BatchGetQueuesRequest) (*BatchGetQueuesResponse, error)
	// Pause a queue: no further job of it is claimed until it is resumed;
	// running jobs finish and new jobs are accepted. Idempotent on a PAUSED
	// queue.
	//
	// See: https://google.aip.dev/136 (Custom methods).
	PauseQueue(context.Context, *PauseQueueRequest) (*v1.Queue, error)
	// Resume a paused queue. Idempotent on a RUNNING queue.
	//
	// See: https://google.aip.dev/136 (Custom methods).
	ResumeQueue(context.Context, *ResumeQueueRequest) (*v1.Queue, error)
	// Create a job in the queue its payload type selects. Fails with
	// FAILED_PRECONDITION when no queue accepts the payload type. A job on a
	// PAUSED queue is accepted and waits. When the job carries a `unique_key`
	// that already has a PENDING job, no job is created and that job is returned
	// instead.
	//
	// See: https://google.aip.dev/133 (Standard methods: Create).
	CreateJob(context.Context, *CreateJobRequest) (*v1.Job, error)
	// Get a job.
	//
	// See: https://google.aip.dev/131 (Standard methods: Get).
	GetJob(context.Context, *GetJobRequest) (*v1.Job, error)
	// Update a job.
	//
	// See: https://google.aip.dev/134 (Standard methods: Update).
	UpdateJob(context.Context, *UpdateJobRequest) (*v1.Job, error)
	// Delete a job. A RUNNING job must be cancelled first.
	//
	// See: https://google.aip.dev/135 (Standard methods: Delete).
	DeleteJob(context.Context, *DeleteJobRequest) (*emptypb.Empty, error)
	// List jobs.
	//
	// See: https://google.aip.dev/132 (Standard methods: List).
	ListJobs(context.Context, *ListJobsRequest) (*ListJobsResponse, error)
	// Get multiple jobs in a single request.
	//
	// See: https://google.aip.dev/231 (Batch methods: Get).
	BatchGetJobs(context.Context, *BatchGetJobsRequest) (*BatchGetJobsResponse, error)
	// Retry a terminal job: returns it to PENDING with its attempts, outcome and
	// `expire_time` reset, so it runs again immediately. Fails with
	// FAILED_PRECONDITION on a PENDING or RUNNING job, and with ALREADY_EXISTS
	// when the job's `unique_key` already has a PENDING job.
	//
	// See: https://google.aip.dev/136 (Custom methods).
	RetryJob(context.Context, *RetryJobRequest) (*v1.Job, error)
	// Cancel a job. A PENDING job is cancelled at once; a RUNNING job is marked
	// CANCELLED and its in-flight processor call is cancelled on a best-effort
	// basis. Fails with FAILED_PRECONDITION on a terminal job.
	//
	// See: https://google.aip.dev/136 (Custom methods).
	CancelJob(context.Context, *CancelJobRequest) (*v1.Job, error)
	// Wait for a job to reach a terminal state, or for the timeout to elapse,
	// whichever comes first, and return it as it is then. Timing out is not an
	// error: callers inspect `state`. The timeout is capped by the server; see
	// [WaitJobRequest.timeout][malonaz.scheduler.scheduler_service.v1.WaitJobRequest.timeout].
	//
	// See: https://google.aip.dev/136 (Custom methods).
	WaitJob(context.Context, *WaitJobRequest) (*v1.Job, error)
	// Report the progress of a RUNNING job. Processors call this with the job
	// name received in the `x-scheduler-job` metadata. Fails with
	// FAILED_PRECONDITION once the job is no longer running, which lets a
	// processor notice a cancellation.
	//
	// See: https://google.aip.dev/136 (Custom methods).
	ReportJobProgress(context.Context, *ReportJobProgressRequest) (*v1.Job, error)
	// Create a schedule in the queue its payload type selects. Fails with
	// INVALID_ARGUMENT when no queue accepts the payload type, when `cron` is
	// not a five-field cron expression, or when `time_zone` is not an IANA
	// zone. The schedule starts ENABLED with `next_schedule_time` at the first
	// occurrence after now.
	//
	// See: https://google.aip.dev/133 (Standard methods: Create).
	CreateSchedule(context.Context, *CreateScheduleRequest) (*v1.Schedule, error)
	// Get a schedule.
	//
	// See: https://google.aip.dev/131 (Standard methods: Get).
	GetSchedule(context.Context, *GetScheduleRequest) (*v1.Schedule, error)
	// Update a schedule. Changing `cron` or `time_zone` recomputes
	// `next_schedule_time` from now; jobs already created are untouched.
	//
	// See: https://google.aip.dev/134 (Standard methods: Update).
	UpdateSchedule(context.Context, *UpdateScheduleRequest) (*v1.Schedule, error)
	// Delete a schedule. Jobs it already created are untouched.
	//
	// See: https://google.aip.dev/135 (Standard methods: Delete).
	DeleteSchedule(context.Context, *DeleteScheduleRequest) (*emptypb.Empty, error)
	// List schedules.
	//
	// See: https://google.aip.dev/132 (Standard methods: List).
	ListSchedules(context.Context, *ListSchedulesRequest) (*ListSchedulesResponse, error)
	// Get multiple schedules in a single request.
	//
	// See: https://google.aip.dev/231 (Batch methods: Get).
	BatchGetSchedules(context.Context, *BatchGetSchedulesRequest) (*BatchGetSchedulesResponse, error)
	// Pause a schedule: no tick is materialized until it is resumed, and
	// `next_schedule_time` is cleared. Jobs already created are untouched.
	// Idempotent on a PAUSED schedule.
	//
	// See: https://google.aip.dev/136 (Custom methods).
	PauseSchedule(context.Context, *PauseScheduleRequest) (*v1.Schedule, error)
	// Resume a paused schedule from the first occurrence after now: ticks that
	// fell within the pause are not caught up. Idempotent on an ENABLED
	// schedule.
	//
	// See: https://google.aip.dev/136 (Custom methods).
	ResumeSchedule(context.Context, *ResumeScheduleRequest) (*v1.Schedule, error)
}

